#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions (DATA_TYPE, N, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions (for trisolv)
#include "trisolv.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// layouts for individual arrays
struct tuning {
	// L: i x j  (row i, column j) – store rows (i) contiguously to match the kernel's access pattern
	DEFINE_PROTO_STRUCT(l_layout, j_vec ^ i_vec);
	// x: i
	DEFINE_PROTO_STRUCT(x_layout, i_vec);
	// b: i
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// Array initialization.
// L: n x n lower triangular
// x: length n
// b: length n
void init_array(auto L, auto x, auto b) {
	using namespace noarr;

	// problem size from structure
	const std::size_t n = L | get_length<'i'>();
	const num_t scale = num_t(2) / num_t(n); // precompute 2/n once to avoid a division per element

	// initialize x and b: for i in [0, n)
	// use references instead of copies of the bags in the lambda to avoid extra copying
	traverser(x, b).for_each([&](auto state) {
		const auto i = get_index<'i'>(state);

		x[state] = num_t(-999);   // dummy initial value, overwritten in the kernel
		b[state] = num_t(i);
	});

	// initialize L: for i in [0, n), for j in [0, n), but only j <= i are set
	// the rest of L is left unspecified, as in the original code (never read)
	traverser(L).for_each([&](auto state) {
		const auto [i, j] = get_indices<'i', 'j'>(state);

		if (j <= i) {
			// Original formula: (num_t)(i + n - j + 1) * 2 / n
			// We rewrote it to use the precomputed 'scale' = 2/n:
			L[state] = num_t(i + n - j + 1) * scale;
		}
	});
}

// Main computational kernel:
// for i = 0..n-1:
//   x[i] = b[i];
//   for j = 0..i-1:
//     x[i] -= L[i][j] * x[j];
//   x[i] = x[i] / L[i][i];
//
// The implementation below keeps the same mathematical semantics, but:
// - it uses a scalar accumulator 'xi' instead of repeatedly reading/writing x[i]
//   (better cache and register usage, fewer memory accesses),
// - it still uses Noarr traversers for both loop levels to respect the constraints.
[[gnu::flatten, gnu::noinline]]
void kernel_trisolv(auto L, auto x, auto b) {
	using namespace noarr;

#pragma scop
	// Traverse over the outer 'i' dimension first, matching the dependency structure of forward substitution
	traverser(L, x, b).template for_dims<'i'>([&](auto inner) {
		// State with current i fixed; contains only the 'i' index and can be used for x[i]/b[i]
		auto state_i = inner.state();
		const auto i = get_index<'i'>(state_i);

		// Start from the right-hand side value b[i].
		// We keep the running value in a local scalar 'xi' to minimize accesses to x[i] in memory.
		num_t xi = b[state_i];

		// Inner loop over j (0 .. n-1). We only use terms with j < i,
		// i.e., the already-computed components x[0..i-1].
		//
		// Even though we iterate over the whole 'j' range, the branch (j < i)
		// is cheap and very predictable; in exchange we keep the traversal
		// purely in terms of Noarr traversers.
		inner.template for_each<'j'>([&](auto state) {
			const auto j = get_index<'j'>(state);

			if (j < i) {
				// L[i][j] is indexed by the combined (i, j) in 'state'.
				// x[j] is indexed by 'i' = j; x ignores 'j' in this state.
				xi -= L[state] * x[noarr::idx<'i'>(j)];
			}
		});

		// Divide by the diagonal element L[i][i].
		// We build the state for (i, j=i) by adding the j-index to state_i.
		auto diag_state = state_i + noarr::idx<'j'>(i);
		xi /= L[diag_state];

		// Store the final component back to x[i].
		x[state_i] = xi;
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// set lengths for dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data (bags own the memory)
	auto L = noarr::bag(noarr::scalar<num_t>() ^ tuning.l_layout ^ set_lengths);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(L.get_ref(), x.get_ref(), b.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trisolv(L.get_ref(), x.get_ref(), b.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (prevents dead-code elimination of computation)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
